export const DELETE = Symbol('delete');

import { cloneValue } from './clone-value.mjs';

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function assertValidContent(value) {
  if (value === undefined || value === DELETE) {
    return;
  }
  if (value === null || typeof value === 'boolean' || typeof value === 'string') {
    return;
  }
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new TypeError('invalid value');
    }
    return;
  }
  if (typeof value === 'function' || typeof value === 'symbol') {
    throw new TypeError('invalid value');
  }
  if (Array.isArray(value)) {
    for (const element of value) {
      if (element === DELETE) {
        throw new TypeError('invalid value');
      }
      assertValidContent(element);
    }
    return;
  }
  if (!isPlainObject(value)) {
    throw new TypeError('invalid value');
  }
  for (const key of Object.keys(value)) {
    assertValidContent(value[key]);
  }
}

function mergeInto(into, layer) {
  for (const key of Object.keys(layer)) {
    const next = layer[key];
    if (next === undefined) {
      continue;
    }
    if (next === DELETE) {
      delete into[key];
      continue;
    }
    const current = into[key];
    if (isPlainObject(current) && isPlainObject(next)) {
      mergeInto(current, next);
      continue;
    }
    into[key] = cloneValue(next);
  }
}

export function mergeLayers(...layers) {
  const result = {};
  for (const layer of layers) {
    if (layer === undefined) {
      continue;
    }
    if (!isPlainObject(layer)) {
      throw new TypeError('invalid layer');
    }
    assertValidContent(layer);
    mergeInto(result, layer);
  }
  return result;
}

